import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Collectors;

class SalesCsvReader {
    record SalesRow(String category, double revenue, boolean valid) {}

    List<SalesRow> readValidRows(Path csvFile) throws IOException {
        try (var lines = Files.lines(csvFile)) {
            return lines.skip(1)
                    .map(SalesCsvReader::parseLine)
                    .filter(SalesRow::valid)
                    .collect(Collectors.toList());
        }
    }

    private static SalesRow parseLine(String line) {
        String[] cols = line.split(",", -1);
        if (cols.length < 2) {
            return new SalesRow("", 0, false);
        }
        try {
            double revenue = Double.parseDouble(cols[1].trim());
            return new SalesRow(cols[0].trim(), revenue, revenue >= 0);
        } catch (NumberFormatException e) {
            return new SalesRow(cols[0].trim(), 0, false);
        }
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;

class TopCategoryReportExporter {
    void exportToJson(Path target, List<Map.Entry<String, Double>> topCategories) throws IOException {
        StringBuilder json = new StringBuilder("[\n");
        for (int i = 0; i < topCategories.size(); i++) {
            var entry = topCategories.get(i);
            json.append("  {\"category\": \"").append(entry.getKey())
                    .append("\", \"revenue\": ").append(entry.getValue()).append("}");
            json.append(i < topCategories.size() - 1 ? ",\n" : "\n");
        }
        json.append("]\n");
        Files.writeString(target, json.toString());
    }
}

